:root {
  --sidebar-bg: var(--appsmith-theme-jewelexSidebarBg, #1F3864);
  --sidebar-text: rgba(255, 255, 255, 0.78);
  --sidebar-text-muted: rgba(255, 255, 255, 0.78);
  --sidebar-text-light: rgba(255, 255, 255, 0.6);
  --sidebar-text-faint: rgba(255, 255, 255, 0.4);
  --sidebar-border: rgba(255, 255, 255, 0.08);
  --sidebar-hover: rgba(255, 255, 255, 0.05);
  --sidebar-active-bg: var(--appsmith-theme-jewelexSidebarActiveBg, #2C5282);
  --sidebar-active-border: #FFFFFF;
  --sidebar-active-text: #FFFFFF;
  --sidebar-icon: rgba(255, 255, 255, 0.78);
  --sidebar-icon-active: #FFFFFF;
  --sidebar-badge-bg: #378ADD;
  --sidebar-badge-text: #FFFFFF;
  --sidebar-fontfamily: var(--appsmith-theme-jewelexSidebarFontFamily, "Inter"), ui-sans-serif, system-ui, sans-serif;
  --sidebar-fontSize: var(--appsmith-theme-jewelexSidebarFontSize, 13.5px);
  --sidebar-heading-fontSize: 11px;
  --sidebar-fontWeight: var(--appsmith-theme-jewelexSidebarFontWeight, 500);
  --sidebar-fontWeight-active: var(--appsmith-theme-jewelexSidebarFontWeightActive, 600);
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html,
body {
  height: 100%;
}

body {
  font-family: var(--sidebar-fontfamily);
  font-size: 13px;
  line-height: 1.6;
  background: #F8FAFC;
  -webkit-font-smoothing: antialiased;
}

a {
  color: inherit;
  text-decoration: none;
}

/* Sidebar */
.sidebar {
  position: fixed;
  inset: 0;
  width: 100%;
  background: var(--sidebar-bg);
  color: var(--sidebar-text);
  display: flex;
  flex-direction: column;
  z-index: 20;
}

/* Brand */
.sidebar .brand {
  padding: 18px 16px;
  border-bottom: 1px solid var(--sidebar-border);
  display: flex;
  align-items: center;
  gap: 10px;
}

.sidebar .brand .logo {
  width: 28px;
  height: 28px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--sidebar-text);
  flex-shrink: 0;
}

.sidebar .brand .logo svg {
  width: 24px;
  height: 24px;
}

.sidebar .brand .b-name {
  font-size: 14px;
  font-weight: var(--sidebar-fontWeight-active);
  line-height: 1.15;
  color: var(--sidebar-text);
}

.sidebar .brand .b-en {
  font-size: 9px;
  color: var(--sidebar-text-faint);
  line-height: 1.3;
}

/* Navigation */
.sidebar .nav {
  flex: 1;
  overflow-y: auto;
  padding: 4px 0 8px 0;
}

.sidebar .nav::-webkit-scrollbar {
  width: 6px;
}

.sidebar .nav::-webkit-scrollbar-thumb {
  background: var(--sidebar-hover);
  border-radius: 999px;
}

.sidebar .nav-section {
  padding: 14px 16px 4px;
  font-size: var(--sidebar-heading-fontSize);
  font-weight: var(--sidebar-fontWeight-active);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--sidebar-text-faint);
}

.sidebar .nav-item {
  display: flex;
  align-items: center;
  gap: 10px;
  height: 38px;
  padding: 0 16px;
  color: var(--sidebar-text-muted);
  font-size: var(--sidebar-fontSize);
  font-weight: var(--sidebar-fontWeight);
  border-left: 3px solid transparent;
  transition: background 0.15s, color 0.15s;
  cursor: pointer;
}

.sidebar .nav-item svg {
  width: 17px;
  height: 17px;
  flex-shrink: 0;
  color: var(--sidebar-icon);
}

.sidebar .nav-item:hover {
  background: var(--sidebar-hover);
}

.sidebar .nav-item.active {
  background: var(--sidebar-active-bg);
  border-left-color: var(--sidebar-active-border);
  color: var(--sidebar-active-text);
  font-weight: var(--sidebar-fontWeight-active);
}

.sidebar .nav-item.active svg {
  color: var(--sidebar-icon-active);
}

.sidebar .nav-item .badge {
  margin-left: auto;
  background: var(--sidebar-badge-bg);
  color: var(--sidebar-badge-text);
  font-size: 10px;
  padding: 1px 6px;
  border-radius: 10px;
  font-weight: 500;
}

/* Footer */
.sidebar .footer {
  margin-top: auto;
  padding: 12px 16px;
  border-top: 1px solid var(--sidebar-border);
  display: flex;
  align-items: center;
  gap: 10px;
}

.sidebar .footer .av {
  width: 30px;
  height: 30px;
  border-radius: 50%;
  background: var(--sidebar-hover);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--sidebar-text);
  font-size: 12px;
  font-weight: 600;
  flex-shrink: 0;
}

.sidebar .footer .who {
  flex: 1;
  line-height: 1.2;
}

.sidebar .footer .who .n {
  font-size: 13px;
  font-weight: var(--sidebar-fontWeight);
  color: var(--sidebar-text);
}

.sidebar .footer .who .r {
  font-size: 10px;
  color: var(--sidebar-text-faint);
}

.sidebar .footer .gear {
  display: none;
}

