:root {
  --accent: var(--appsmith-theme-jewelexAccentBlue, #2B8A7E);
  --accent-600: var(--appsmith-theme-jewelexAccentBlueDark, #21665D);
  --accent-050: #EEF9F7;
  --accent-100: #E6F4F1;
  --paper: var(--appsmith-theme-jewelexBgPage, #F7FAFC);
  --panel: var(--appsmith-theme-jewelexCardBg, #FFFFFF);
  --line: #E2E8F0;
  --line-soft: #EDF2F7;
  --text: var(--appsmith-theme-jewelexTextPrimary, #1A202C);
  --text-dim: var(--appsmith-theme-jewelexTextSecondary, #4A5568);
  --text-mute: var(--appsmith-theme-jewelexTextPlaceholder, #718096);
  --success: #16A34A;
  --danger: #E53E3E;
  --font-body: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-body);
  background: var(--paper);
  color: var(--text);
  -webkit-font-smoothing: antialiased;
}

.wrap {
  max-width: 100%;
  margin: 0 auto;
  padding: 24px 20px 48px;
}

button {
  font-family: inherit;
  cursor: pointer;
}

input {
  font-family: inherit;
}

.page-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  margin-bottom: 18px;
  gap: 16px;
}

.page-head h1 {
  font-size: 22px;
  font-weight: 700;
  line-height: 1.2;
}

.page-head p {
  font-size: 11px;
  color: var(--text-mute);
  margin-top: 2px;
}

.btn {
  border-radius: 6px;
  font-weight: 500;
  border: 1px solid transparent;
  padding: 7px 16px;
  font-size: 12px;
  transition: all 0.15s;
}

.btn:hover {
  opacity: 0.9;
}

.btn-solid {
  background: var(--accent);
  color: #fff;
  border-color: var(--accent);
}

.btn-outline {
  background: var(--panel);
  color: var(--text-dim);
  border-color: var(--line);
}

.btn[disabled] {
  background: #E2E8F0 !important;
  border-color: #E2E8F0 !important;
  color: #94A3B8 !important;
  cursor: not-allowed !important;
}

.card {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 8px;
}

.card.pad {
  padding: 12px;
}

.mb4 {
  margin-bottom: 16px;
}

.pipe {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
  margin-bottom: 18px;
}

.pipe .box {
  border: 1px solid;
  border-radius: 12px;
  padding: 14px 16px;
}

.pipe .box .top {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.pipe .box .lbl {
  font-size: 11.5px;
  font-weight: 500;
}

.pipe .box .num {
  font-size: 24px;
  font-weight: 700;
  margin-top: 6px;
  line-height: 1;
}

.search {
  position: relative;
  max-width: 420px;
}

.search svg {
  position: absolute;
  left: 12px;
  top: 9px;
  color: var(--text-mute);
}

.search input {
  width: 100%;
  border: 1px solid var(--line);
  border-radius: 6px;
  padding: 8px 12px 8px 34px;
  font-size: 12px;
  outline: none;
}

.search input:focus {
  border-color: var(--accent);
}

/* Top Pagination Row (matches NOHD clinic layout) */
.table-head-row {
  display: flex;
  align-items: center;
  justify-content: flex-end; /* info + stepper aligned to the right */
  padding: 10px 16px;
  border-bottom: 1px solid var(--line);
  font-size: 12px;
  color: var(--text-dim);
  background: var(--panel);
  flex-wrap: wrap;
  gap: 10px;
}

.page-info {
  font-size: 12px;
  font-weight: 500;
  color: var(--text-dim);
}

.page-controls {
  display: flex;
  align-items: center;
  gap: 4px;
  padding-left: 12px;
  border-left: 1px solid var(--line); /* divider between info and stepper */
}

.page-btn {
  min-width: 26px;
  height: 26px;
  border-radius: 5px;
  border: 1px solid var(--line);
  background: var(--panel);
  color: var(--text);
  font-size: 12px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all 0.15s;
}

.page-btn.active {
  background: var(--accent);
  border-color: var(--accent);
  color: #fff;
  font-weight: 600;
}

.page-btn:hover:not(.active):not(:disabled) {
  background: var(--line-soft);
}

.page-btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.page-ellipsis {
  padding: 0 4px;
  color: var(--text-mute);
}

.tbl-scroll {
  overflow-x: auto;
}

table {
  width: 100%;
  font-size: 12px;
  border-collapse: collapse;
}

thead tr {
  background: var(--line-soft);
  border-bottom: 1px solid var(--line);
}

th {
  text-align: left;
  padding: 10px 14px;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--text-mute);
}

tbody tr {
  border-bottom: 1px solid var(--line-soft);
  transition: background 0.15s;
}

tbody tr:hover {
  background: var(--paper);
}

td {
  padding: 12px 14px;
  color: var(--text);
  vertical-align: middle;
}

.link {
  background: none;
  border: 0;
  font-size: 12px;
  font-weight: 600;
  color: var(--accent);
}

.link:hover {
  text-decoration: underline;
}

.dim {
  color: var(--text-dim);
}

.badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 3px 10px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.02em;
}

.link.disabled {
  color: #94A3B8 !important;
  cursor: not-allowed !important;
  text-decoration: none !important;
  pointer-events: none;
}

/* Overlay, Modal, Dropdown & Drawers */
.overlay {
  position: fixed;
  inset: 0;
  z-index: 50;
  background: rgba(15, 23, 42, 0.45);
  display: flex;
  align-items: flex-start; /* center se hata kar top pe aligned */
  justify-content: center;
  padding: 40px 16px 20px; /* modal upar se 40px gap par khulega */
  overflow-y: auto;
}

.modal {
  width: 100%;
  max-width: 560px;
  max-height: 90vh;
  background: var(--panel);
  border-radius: 12px;
  box-shadow: 0 24px 60px rgba(15, 23, 42, 0.22);
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.modal-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  padding: 20px 22px 16px;
  border-bottom: 1px solid var(--line);
}

.modal-head .t {
  font-size: 17px;
  font-weight: 600;
}

.modal-head .s {
  font-size: 13px;
  color: var(--text-dim);
  margin-top: 2px;
}

.xbtn {
  background: none;
  border: 0;
  padding: 4px;
  border-radius: 4px;
  color: var(--text-dim);
  line-height: 0;
  cursor: pointer;
}

.xbtn:hover {
  background: var(--line-soft);
}

.modal-body {
  padding: 18px 22px;
  display: flex;
  flex-direction: column;
  gap: 18px;
  overflow-y: auto;
  flex: 1;
}

.modal-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 22px;
  border-top: 1px solid var(--line);
}

.tooltip-wrap {
  position: relative;
  display: inline-flex;
}

.tooltip-bubble {
  position: absolute;
  bottom: calc(100% + 8px);
  right: 0;
  background: #0F172A;
  color: #F8FAFC;
  font-size: 11.5px;
  font-weight: 500;
  padding: 6px 12px;
  border-radius: 6px;
  white-space: nowrap;
  pointer-events: none;
  opacity: 0;
  transform: translateY(4px);
  transition: all 0.18s ease;
}

.tooltip-bubble::after {
  content: "";
  position: absolute;
  top: 100%;
  right: 16px;
  border-width: 5px;
  border-style: solid;
  border-color: #0F172A transparent transparent transparent;
}

.tooltip-wrap:hover .tooltip-bubble {
  opacity: 1;
  transform: translateY(0);
}

.grid2 {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}

.grid4 {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 10px;
}

label.fl {
  font-size: 13px;
  font-weight: 500;
  color: var(--text-dim);
}

.fld {
  width: 100%;
  border: 1px solid var(--line);
  border-radius: 6px;
  padding: 8px 12px;
  font-size: 13px;
  margin-top: 4px;
  color: var(--text);
  background: var(--panel);
  outline: none;
}

.fld:focus {
  border-color: var(--accent);
}

.sect-lbl {
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  font-weight: 600;
  color: var(--text-mute);
  margin-bottom: 8px;
}

.u-select {
  position: relative;
  width: 100%;
  margin-top: 4px;
}

.u-select-btn {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8.5px 12px;
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 6px;
  font-size: 13px;
  color: var(--text);
  cursor: pointer;
  text-align: left;
}

.u-select-btn .ph {
  color: var(--text-mute);
}

.u-select-btn .arrow {
  color: var(--text-mute);
  display: flex;
}

.u-floating-menu {
  position: fixed;
  background: #FFFFFF;
  border: 1px solid var(--line);
  border-radius: 8px;
  box-shadow: 0 10px 28px -4px rgba(15, 23, 42, 0.16);
  padding: 4px;
  max-height: 200px;
  overflow-y: auto;
  z-index: 9999;
  display: none;
}

.u-floating-menu.show {
  display: block;
}

.u-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 10px;
  font-size: 13px;
  color: var(--text-dim);
  border-radius: 5px;
  cursor: pointer;
}

.u-item:hover {
  background: var(--line-soft);
  color: var(--text);
}

.u-item.sel {
  background: var(--accent-050);
  color: var(--accent);
  font-weight: 600;
}

.u-item .check {
  color: var(--accent);
  opacity: 0;
}

.u-item.sel .check {
  opacity: 1;
}

.party {
  text-align: left;
  border: 1px solid var(--line);
  background: var(--panel);
  border-radius: 10px;
  padding: 12px;
}

.party.on {
  border: 2px solid var(--accent);
  background: var(--accent-050);
}

.party .ic {
  margin-top: 6px;
  color: var(--text-mute);
}

.party.on .ic {
  color: var(--accent);
}

.party .nm {
  font-size: 14px;
  font-weight: 600;
  margin-top: 6px;
}

.party .sb {
  font-size: 11px;
  color: var(--text-dim);
  margin-top: 2px;
}

.pill {
  display: inline-block;
  padding: 3px 9px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 600;
}

.drawer-overlay {
  position: fixed;
  inset: 0;
  z-index: 50;
  background: rgba(15, 23, 42, 0.35);
  display: flex;
  justify-content: flex-end;
}

.drawer {
  width: 460px;
  max-width: 100%;
  height: 100%;
  background: var(--panel);
  display: flex;
  flex-direction: column;
}

.drawer-head {
  padding: 20px 20px 16px;
  border-bottom: 1px solid var(--line);
}

.drawer-body {
  flex: 1;
  overflow-y: auto;
  padding: 20px;
}

.drawer-foot {
  padding: 16px 20px;
  border-top: 1px solid var(--line);
}

.kv {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 14px 16px;
}

.kv .k {
  font-size: 11px;
  color: var(--text-mute);
}

.kv .v {
  font-size: 13px;
  margin-top: 3px;
  word-break: break-all;
}

.right {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
}

#toasts {
  position: fixed;
  right: 20px;
  bottom: 20px;
  z-index: 100;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.toast {
  background: var(--panel);
  border: 1px solid var(--line);
  border-left: 3px solid var(--accent);
  border-radius: 8px;
  padding: 10px 14px;
  font-size: 13px;
}

.toast.ok {
  border-left-color: var(--success);
}

.toast.err {
  border-left-color: var(--danger);
}

/* Table Loader Overlay */
.tbl-loading-wrap {
  position: relative;
  min-height: 200px;
}

.tbl-loader {
  position: absolute;
  inset: 0;
  background: rgba(255, 255, 255, 0.75);
  backdrop-filter: blur(1px);
  display: none;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  z-index: 20;
  gap: 10px;
  font-size: 13px;
  font-weight: 500;
  color: var(--text-dim);
}

.tbl-loader.show {
  display: flex;
}

.spinner {
  width: 28px;
  height: 28px;
  border: 3px solid #E2E8F0;
  border-top-color: var(--accent);
  border-radius: 50%;
  animation: spin 0.75s linear infinite;
}

@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}
/* Table Loader Overlay */
.tbl-loading-wrap {
  position: relative;
  min-height: 260px;
}

.tbl-loader {
  position: absolute;
  inset: 0;
  background: rgba(255, 255, 255, 0.85);
  backdrop-filter: blur(2px);
  display: none;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  z-index: 30;
  gap: 12px;
  font-size: 13px;
  font-weight: 600;
  color: var(--text-dim);
}

.tbl-loader.show {
  display: flex !important;
}

.spinner {
  width: 32px;
  height: 32px;
  border: 3px solid #E2E8F0;
  border-top-color: var(--accent);
  border-radius: 50%;
  animation: spin 0.7s linear infinite;
}

@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}
/* Full Screen / Viewport Blocking Loader */
.screen-loader-overlay {
  position: fixed;
  inset: 0;
  z-index: 99999;
  background: rgba(15, 23, 42, 0.6);
  backdrop-filter: blur(3px);
  display: none;
  align-items: center;
  justify-content: center;
}

.screen-loader-overlay.show {
  display: flex !important;
}

.screen-loader-box {
  background: var(--panel);
  border: 1px solid var(--line);
  padding: 24px 32px;
  border-radius: 12px;
  box-shadow: 0 20px 40px rgba(0, 0, 0, 0.25);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 14px;
}

.spinner.lg {
  width: 38px;
  height: 38px;
  border-width: 3.5px;
  border-color: #E2E8F0;
  border-top-color: var(--accent);
}

.screen-loader-text {
  font-size: 13.5px;
  font-weight: 600;
  color: var(--text);
}

/* ============ Filter Bar (search + KYC status + KYC form) ============ */
.filter-bar {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}

.filter-bar .search {
  flex: 1 1 260px;
}

.filter-select {
  width: 170px;
  margin-top: 0;
}

.filter-select.wide {
  width: 250px;
}

.filter-select .u-select-btn {
  padding: 7.5px 12px;
  font-size: 12px;
  gap: 8px;
}

.filter-select .u-select-btn > span:first-child {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.filter-select .u-select-btn .lbl-k {
  color: var(--text-mute);
  margin-right: 4px;
  font-weight: 500;
}

.filter-select.has-val .u-select-btn {
  border-color: var(--accent);
  background: var(--accent-050);
  color: var(--accent);
  font-weight: 600;
}

.filter-select.has-val .u-select-btn .arrow {
  color: var(--accent);
}

#clearFilters {
  padding: 7px 12px;
}

@media (max-width: 640px) {
  .filter-select, .filter-select.wide {
    width: 100%;
  }
}

