function initApp() {
  const TEAL = "#2B8A7E";
  const BADGES = {
    "INVITED": {
      bg: "#E0F2FE",
      fg: "#0369A1",
      dot: "#0284C7"
    },
    "UNDER REVIEW": {
      bg: "#FEF3C7",
      fg: "#92400E",
      dot: "#D97706"
    },
    "APPROVED": {
      bg: "#DCFCE7",
      fg: "#166534",
      dot: "#16A34A"
    },
    "REJECTED": {
      bg: "#FEE2E2",
      fg: "#991B1B",
      dot: "#DC2626"
    }
  };
  const COMPANY_OPTIONS = ["Jewelex India Pvt Ltd", "Jewelex New York"];
  let vendors = [];
  let isInvitingVendor = false; // Flag to hold screen loader until sync completes
  let lastVendorsSignature = null; // Guards against unnecessary re-renders on unrelated model changes

  let currentPage = typeof appsmith !== "undefined" && appsmith.model?.page || 1;
  let pageSize = typeof appsmith !== "undefined" && appsmith.model?.pageSize || 10;
  let totalRecords = typeof appsmith !== "undefined" && appsmith.model?.totalRecords || 0;
  const counts = {
    invited: 0,
    underReview: 0,
    approved: 0,
    rejected: 0
  };
  const ICON = {
    mail: '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="2" y="4" width="20" height="16" rx="2"/><path d="m22 7-10 6L2 7"/></svg>',
    clock: '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/></svg>',
    check: '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="9"/><path d="m8.5 12.5 2.5 2.5 4.5-5"/></svg>',
    x: '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="9"/><path d="m9 9 6 6M15 9l-6 6"/></svg>',
    close: '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M18 6 6 18M6 6l12 12"/></svg>',
    building: '<svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><rect x="4" y="3" width="16" height="18" rx="2"/><path d="M9 8h.01M15 8h.01M9 12h.01M15 12h.01M10 21v-4h4v4"/></svg>',
    plane: '<svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M3.5 19h17M2 12l4 1 9-8 1.5 1.5-5 7.5 6 1.5"/></svg>',
    users: '<svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="9" cy="8" r="3.2"/><path d="M2.5 20a6.5 6.5 0 0 1 13 0M17 11a3 3 0 1 0 0-6M18 20a6 6 0 0 0-2-4.5"/></svg>',
    factory: '<svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M3 20V10l5 3V10l5 3V10l6 3v7z"/><path d="M3 20h18M7 20v-3M12 20v-3M17 20v-3"/></svg>',
    chevronDown: '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="m6 9 6 6 6-6"/></svg>',
    tick: '<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.6"><path d="M20 6 9 17l-5-5"/></svg>'
  };
  const PARTIES = [{
    id: "local",
    tag: "Local",
    tagBg: "#F1F5F9",
    tagFg: "#475569",
    icon: ICON.building,
    label: "Local",
    sub: "India-based supplier/customer"
  }, {
    id: "import",
    tag: "Import",
    tagBg: "#EFF6FF",
    tagFg: "#1D4ED8",
    icon: ICON.plane,
    label: "Import",
    sub: "Foreign supplier"
  }, {
    id: "customer",
    tag: "Customer",
    tagBg: "#F5F3FF",
    tagFg: "#6D28D9",
    icon: ICON.users,
    label: "Customer",
    sub: "Local / export customer"
  }, {
    id: "seepz",
    tag: "SEEPZ",
    tagBg: "#CCFBF1",
    tagFg: "#0F766E",
    icon: ICON.factory,
    label: "SEEPZ",
    sub: "SEEPZ unit vendor"
  }];
  const CATEGORIES = {
    local: ["Raw material (RM)", "Other than RM"],
    import: ["Raw material (RM)", "Other than RM"],
    customer: ["Local customer", "Export customer"],
    seepz: ["Raw material (RM)", "Other than RM"]
  };
  const PARTY_CODE = {
    local: "LOCAL",
    import: "IMPORT",
    customer: "CUSTOMER",
    seepz: "SEEPZ"
  };
  const CATEGORY_CODE = {
    "Raw material (RM)": "RM",
    "Other than RM": "OTHER_THAN_RM",
    "Local customer": "LOCAL_CUSTOMER",
    "Export customer": "EXPORT_CUSTOMER"
  };
  const PARTY_LABEL = {
    LOCAL: "Local",
    IMPORT: "Import",
    CUSTOMER: "Customer",
    SEEPZ: "SEEPZ"
  };
  const CATEGORY_LABEL = {
    RM: "Raw material (RM)",
    OTHER_THAN_RM: "Other than RM",
    LOCAL_CUSTOMER: "Local customer",
    EXPORT_CUSTOMER: "Export customer"
  };
  const STATUS_LABEL = {
    DRAFT: "INVITED",
    SUBMITTED: "UNDER REVIEW",
    CHANGES_REQUESTED: "REJECTED",
    APPROVED: "APPROVED",
    LN_COMPLETED: "APPROVED",
    REJECTED: "KYC REJECTED"
  };

  /* ============ Filters (KYC Status + KYC Form) ============ */
  const filterState = {
    status: "",
    form: ""
  }; // "" = All

  const STATUS_FILTER_OPTIONS = [{
    value: "",
    label: "All statuses"
  }, {
    value: "INVITED",
    label: "Invited"
  }, {
    value: "UNDER REVIEW",
    label: "Under Review"
  }, {
    value: "APPROVED",
    label: "Approved"
  }, {
    value: "REJECTED",
    label: "Rejected"
  }];

  // KYC form = party type + category, value format "PARTY|CATEGORY" e.g. "LOCAL|RM"
  function buildFormFilterOptions() {
    const opts = [{
      value: "",
      label: "All KYC forms"
    }];
    PARTIES.forEach(p => {
      CATEGORIES[p.id].forEach(cat => {
        opts.push({
          value: PARTY_CODE[p.id] + "|" + CATEGORY_CODE[cat],
          label: p.label + " - " + cat
        });
      });
    });
    return opts;
  }
  const FORM_FILTER_OPTIONS = buildFormFilterOptions();
  function isServiceSupplierApplicable(partyId, categoryLabel) {
    return partyId === "import" && CATEGORY_CODE[categoryLabel] === "OTHER_THAN_RM";
  }
  const $ = (s, r) => (r || document).querySelector(s);
  const esc = s => String(s || "").replace(/[&<>"']/g, c => ({
    "&": "&amp;",
    "<": "&lt;",
    ">": "&gt;",
    '"': "&quot;",
    "'": "&#39;"
  })[c]);
  function currentSearch() {
    return $("#vendorSearch") ? $("#vendorSearch").value : "";
  }
  function renderFilterButtons() {
    const sBtn = $("#statusFilterBtn");
    const fBtn = $("#formFilterBtn");
    if (!sBtn || !fBtn) return;
    const sOpt = STATUS_FILTER_OPTIONS.find(o => o.value === filterState.status);
    const fOpt = FORM_FILTER_OPTIONS.find(o => o.value === filterState.form);
    sBtn.innerHTML = `<span><span class="lbl-k">Status:</span>${esc(filterState.status && sOpt ? sOpt.label : "All")}</span>
                      <span class="arrow">${ICON.chevronDown}</span>`;
