      const vComp = (v.companyName || v.company_name || "").toLowerCase();
      const vType = (v.kycType || "").toLowerCase();
      const matchesSearch = !q || vName.includes(q) || vEmail.includes(q) || vComp.includes(q) || vType.includes(q);
      const vStatus = v.kycStatus || v.status || "INVITED";
      const matchesStatus = !filterState.status || vStatus === filterState.status;
      const vForm = String(v.party_type || "").toUpperCase() + "|" + String(v.category || "").toUpperCase();
      const matchesForm = !filterState.form || vForm === filterState.form;
      return matchesSearch && matchesStatus && matchesForm;
    });
    if (!filtered.length) {
      const hasFilters = q || filterState.status || filterState.form;
      $("#vendorBody").innerHTML = `
        <tr>
          <td colspan="6" style="text-align:center;padding:36px 16px;color:#94A3B8">
            ${hasFilters ? "No vendors match the current filters." : "No vendors found."}
