  // Signature is used to decide whether an incoming model update actually
  // changed vendor data (so we don't blow away scroll/focus/search state
  // on every unrelated model change, e.g. sendInvite's status ticking over).
  function computeSignature(list) {
    return JSON.stringify((list || []).map(v => (v._id || v.case_id || "") + "|" + (v.status || "") + "|" + (v.vendor_contact_email || v.vendorEmail || "") + "|" + (v.vendor_working_name || v.vendorName || "")));
