  function openDropdownPortal(targetTriggerEl, options, selectedValue, onSelect) {
    if (activeDropdown === targetTriggerEl) {
      closeAllDropdowns();
      return;
    }
    closeAllDropdowns();
    const parentSelect = targetTriggerEl.closest(".u-select");
    if (parentSelect) parentSelect.classList.add("active");
    activeDropdown = targetTriggerEl;
    const rect = targetTriggerEl.getBoundingClientRect();
    const spaceBelow = window.innerHeight - rect.bottom;
    const menuHeight = Math.min(options.length * 36 + 10, 200);
    const openUpwards = spaceBelow < menuHeight && rect.top > menuHeight;
    const menu = document.createElement("div");
    menu.className = "u-floating-menu show";
    menu.style.width = rect.width + "px";
    menu.style.left = rect.left + "px";
    if (openUpwards) {
      menu.style.bottom = window.innerHeight - rect.top + 4 + "px";
      menu.style.top = "auto";
    } else {
      menu.style.top = rect.bottom + 4 + "px";
      menu.style.bottom = "auto";
    }
    menu.innerHTML = options.map(opt => `
      <div class="u-item ${selectedValue === opt.value ? "sel" : ""}" data-val="${esc(opt.value)}">
        <span>${esc(opt.label)}</span>
        <span class="check">${ICON.tick}</span>
      </div>
