    input.style.borderColor = dup ? "#DC2626" : "";
    input.style.background = dup ? "#FEF2F2" : "";
  }
  function validateEmailFormat(email) {
    return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(email).trim());
