    plane: '<svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M3.5 19h17M2 12l4 1 9-8 1.5 1.5-5 7.5 6 1.5"/></svg>',
    users: '<svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="9" cy="8" r="3.2"/><path d="M2.5 20a6.5 6.5 0 0 1 13 0M17 11a3 3 0 1 0 0-6M18 20a6 6 0 0 0-2-4.5"/></svg>',
    factory: '<svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M3 20V10l5 3V10l5 3V10l6 3v7z"/><path d="M3 20h18M7 20v-3M12 20v-3M17 20v-3"/></svg>',
    chevronDown: '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="m6 9 6 6 6-6"/></svg>',
    tick: '<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.6"><path d="M20 6 9 17l-5-5"/></svg>'
  };

  const PARTIES = [
    { id: "local", tag: "Local", tagBg: "#F1F5F9", tagFg: "#475569", icon: ICON.building, label: "Local", sub: "India-based supplier/customer" },
    { id: "import", tag: "Import", tagBg: "#EFF6FF", tagFg: "#1D4ED8", icon: ICON.plane, label: "Import", sub: "Foreign supplier" },
    { id: "customer", tag: "Customer", tagBg: "#F5F3FF", tagFg: "#6D28D9", icon: ICON.users, label: "Customer", sub: "Local / export customer" },
    { id: "seepz", tag: "SEEPZ", tagBg: "#CCFBF1", tagFg: "#0F766E", icon: ICON.factory, label: "SEEPZ", sub: "SEEPZ unit vendor" },
  ];

  const CATEGORIES = {
    local: ["Raw material (RM)", "Other than RM"],
    import: ["Raw material (RM)", "Other than RM"],
    customer: ["Local customer", "Export customer"],
    seepz: ["Raw material (RM)", "Other than RM"],
  };

  const PARTY_CODE = { local: "LOCAL", import: "IMPORT", customer: "CUSTOMER", seepz: "SEEPZ" };
  const CATEGORY_CODE = {
    "Raw material (RM)": "RM",
    "Other than RM": "OTHER_THAN_RM",
    "Local customer": "LOCAL_CUSTOMER",
    "Export customer": "EXPORT_CUSTOMER",
  };

  const PARTY_LABEL = { LOCAL: "Local", IMPORT: "Import", CUSTOMER: "Customer", SEEPZ: "SEEPZ" };
  const CATEGORY_LABEL = {
    RM: "Raw material (RM)",
    OTHER_THAN_RM: "Other than RM",
    LOCAL_CUSTOMER: "Local customer",
    EXPORT_CUSTOMER: "Export customer",
  };

  const STATUS_LABEL = {
    DRAFT: "INVITED",
    SUBMITTED: "UNDER REVIEW",
    CHANGES_REQUESTED: "REJECTED",
    APPROVED: "APPROVED",
    LN_COMPLETED: "APPROVED",
    REJECTED: "KYC REJECTED",
  };

  /* ============ Filters (KYC Status + KYC Form) ============ */
  const filterState = { status: "", form: "" }; // "" = All

  const STATUS_FILTER_OPTIONS = [
    { value: "", label: "All statuses" },
    { value: "INVITED", label: "Invited" },
    { value: "UNDER REVIEW", label: "Under Review" },
    { value: "APPROVED", label: "Approved" },
    { value: "REJECTED", label: "Rejected" },
  ];

  // KYC form = party type + category, value format "PARTY|CATEGORY" e.g. "LOCAL|RM"
  function buildFormFilterOptions() {
    const opts = [{ value: "", label: "All KYC forms" }];
    PARTIES.forEach(p => {
      CATEGORIES[p.id].forEach(cat => {
        opts.push({
          value: PARTY_CODE[p.id] + "|" + CATEGORY_CODE[cat],
          label: p.label + " - " + cat,
        });
      });
    });
    return opts;
  }
  const FORM_FILTER_OPTIONS = buildFormFilterOptions();

  function isServiceSupplierApplicable(partyId, categoryLabel) {
    return partyId === "import" && CATEGORY_CODE[categoryLabel] === "OTHER_THAN_RM";
  }

  const $ = (s, r) => (r || document).querySelector(s);
  const esc = s => String(s || "").replace(/[&<>"']/g, c => ({ "&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;" }[c]));

  function currentSearch() {
    return $("#vendorSearch") ? $("#vendorSearch").value : "";
  }

  function renderFilterButtons() {
    const sBtn = $("#statusFilterBtn");
    const fBtn = $("#formFilterBtn");
    if (!sBtn || !fBtn) return;

    const sOpt = STATUS_FILTER_OPTIONS.find(o => o.value === filterState.status);
    const fOpt = FORM_FILTER_OPTIONS.find(o => o.value === filterState.form);

    sBtn.innerHTML = `<span><span class="lbl-k">Status:</span>${esc(filterState.status && sOpt ? sOpt.label : "All")}</span>
                      <span class="arrow">${ICON.chevronDown}</span>`;
    fBtn.innerHTML = `<span><span class="lbl-k">KYC Form:</span>${esc(filterState.form && fOpt ? fOpt.label : "All")}</span>
                      <span class="arrow">${ICON.chevronDown}</span>`;

    sBtn.closest(".u-select").classList.toggle("has-val", !!filterState.status);
    fBtn.closest(".u-select").classList.toggle("has-val", !!filterState.form);

    const clr = $("#clearFilters");
    if (clr) clr.style.display = (filterState.status || filterState.form) ? "" : "none";
  }

  // Screen-level blocking loader
  function showScreenLoader(show, text) {
    const el = $("#screenLoader");
    const txt = $("#screenLoaderMsg");
    if (!el) return;
    if (show) {
      if (txt && text) txt.textContent = text;
      el.classList.add("show");
    } else {
      el.classList.remove("show");
    }
  }

  function setTableLoader(show, text) {
    const el = $("#tableLoader");
    const txtEl = $("#tableLoaderText");
    if (!el) return;
    if (show) {
      if (txtEl && text) txtEl.textContent = text;
      el.classList.add("show");
    } else {
      el.classList.remove("show");
    }
  }

  function wireCloseHandlers(root, selector, closeFn) {
    root.querySelectorAll(selector).forEach(el => {
      if (el.classList.contains("xbtn")) {
        el.addEventListener("click", () => closeFn());
      } else {
        el.addEventListener("click", ev => { if (ev.target === el) closeFn(); });
      }
    });
  }

  function toast(msg, kind) {
    const el = document.createElement("div");
    el.className = "toast" + (kind ? " " + kind : "");
    el.textContent = msg;
    $("#toasts").appendChild(el);
    setTimeout(() => el.remove(), 2600);
  }

  function badge(status) {
    const s = BADGES[status] || { bg: "#E0F2FE", fg: "#0369A1", dot: "#0284C7" };
    return `<span class="badge" style="background:${s.bg};color:${s.fg}">
      <span style="width:6px;height:6px;border-radius:999px;background:${s.dot}"></span>
      ${esc(status)}
    </span>`;
  }

  function normalizeVendor(doc) {
    if (!doc) return null;
    if (doc.vendorName && doc.kycStatus) return doc;

    const partyCode = String(doc.party_type || "").toUpperCase();
    const categoryCode = String(doc.category || "").toUpperCase();
    const partyLabel = PARTY_LABEL[partyCode] || doc.party_type || "-";
    const categoryLabel = CATEGORY_LABEL[categoryCode] || doc.category || "";
    const isSvc = doc.service_supplier === true;

    return {
      caseId: doc._id || doc.case_id || null,
      submissionId: (doc.current_draft && doc.current_draft.submission_id) || null,
      vendorName: doc.vendor_working_name || doc.vendorName || doc.name || "-",
      vendorEmail: doc.vendor_contact_email || doc.vendorEmail || doc.email || "-",
      companyName: doc.company_name || doc.companyName || "-",
      partyType: partyLabel,
      kycType: partyLabel + (categoryLabel ? " - " + categoryLabel : "") + (isSvc ? " (Service)" : ""),
      kycStatus: STATUS_LABEL[String(doc.status || "").toUpperCase()] || "INVITED",
      createdAt: doc.created_at || doc.createdAt || null,
      party_type: partyCode,
      category: categoryCode,
      service_supplier: doc.service_supplier === true
    };
  }

  function recalculateCounts() {
    counts.invited = vendors.filter(v => (v.kycStatus || v.status || "INVITED") === "INVITED").length;
    counts.underReview = vendors.filter(v => (v.kycStatus || v.status) === "UNDER REVIEW").length;
    counts.approved = vendors.filter(v => (v.kycStatus || v.status) === "APPROVED").length;
    counts.rejected = vendors.filter(v => (v.kycStatus || v.status) === "REJECTED").length;
  }

  function renderPipelineCards() {
    const cards = [
      { label: "Invited", count: counts.invited, bg: "#F0F9FF", border: "#BAE6FD", fg: "#0284C7", icon: ICON.mail },
      { label: "Under Review", count: counts.underReview, bg: "#FFFBEB", border: "#FDE68A", fg: "#D97706", icon: ICON.clock },
      { label: "Approved", count: counts.approved, bg: "#F0FDF4", border: "#BBF7D0", fg: "#16A34A", icon: ICON.check },
      { label: "Rejected", count: counts.rejected, bg: "#FFF1F2", border: "#FECDD3", fg: "#E11D48", icon: ICON.x },
    ];

    $("#pipeCards").innerHTML = cards.map(c => `
      <div class="box" style="background:${c.bg};border-color:${c.border}">
        <div class="top">
          <div class="lbl" style="color:${c.fg}">${c.label}</div>
          <span style="color:${c.fg};line-height:0">${c.icon}</span>
        </div>
        <div class="num" style="color:${c.fg}">${c.count}</div>
      </div>`).join("");
  }

  async function goToPage(newPage) {
    if (newPage === currentPage) return;
    currentPage = newPage;
    setTableLoader(true, "Loading page " + newPage + "...");

    if (typeof appsmith !== "undefined") {
      await appsmith.updateModel({ page: currentPage });
      appsmith.triggerEvent("onPageChange");
    }
  }

  function renderPagination() {
    const infoEl = document.getElementById("page-info");
    const ctrlEl = document.getElementById("page-controls");
    if (!infoEl || !ctrlEl) return;

    const totalPages = Math.max(1, Math.ceil(totalRecords / pageSize));
    if (currentPage > totalPages) currentPage = totalPages;

    const start = totalRecords ? (currentPage - 1) * pageSize + 1 : 0;
    const end = Math.min(currentPage * pageSize, totalRecords);

    infoEl.textContent = totalRecords
      ? `Showing ${start}-${end} of ${totalRecords} vendors`
      : `0 vendors`;

    // Stepper is always visible (even for a single page it shows "1").
    // Pattern: 1 2 3 … 10  |  1 … 4 5 6 … 10  |  1 … 8 9 10
    const pages = [];
    if (totalPages <= 5) {
      for (let i = 1; i <= totalPages; i++) pages.push(i);
    } else if (currentPage <= 3) {
      const upto = Math.max(3, currentPage + 1);
      for (let i = 1; i <= upto; i++) pages.push(i);
      pages.push("…", totalPages);
    } else if (currentPage >= totalPages - 2) {
      pages.push(1, "…");
      const from = Math.min(totalPages - 2, currentPage - 1);
      for (let i = from; i <= totalPages; i++) pages.push(i);
    } else {
      pages.push(1, "…", currentPage - 1, currentPage, currentPage + 1, "…", totalPages);
    }

    let html = `<button class="page-btn" id="page-prev" ${currentPage === 1 ? "disabled" : ""}>‹</button>`;
    pages.forEach(p => {
      html += p === "…"
        ? `<span class="page-ellipsis">…</span>`
        : `<button class="page-btn${p === currentPage ? " active" : ""}" data-page="${p}">${p}</button>`;
    });
    html += `<button class="page-btn" id="page-next" ${currentPage === totalPages ? "disabled" : ""}>›</button>`;
    ctrlEl.innerHTML = html;

    ctrlEl.querySelectorAll("[data-page]").forEach(btn => {
      btn.addEventListener("click", () => goToPage(Number(btn.dataset.page)));
    });
    document.getElementById("page-prev")?.addEventListener("click", () => {
      if (currentPage > 1) goToPage(currentPage - 1);
    });
    document.getElementById("page-next")?.addEventListener("click", () => {
      if (currentPage < totalPages) goToPage(currentPage + 1);
    });
  }

  function renderVendors(filter) {
    const q = (filter || "").trim().toLowerCase();

    const filtered = vendors.filter(v => {
      const vName = (v.vendorName || v.name || "").toLowerCase();
      const vEmail = (v.vendorEmail || v.email || "").toLowerCase();
      const vComp = (v.companyName || v.company_name || "").toLowerCase();
      const vType = (v.kycType || "").toLowerCase();
      const matchesSearch = !q || vName.includes(q) || vEmail.includes(q) || vComp.includes(q) || vType.includes(q);

      const vStatus = v.kycStatus || v.status || "INVITED";
      const matchesStatus = !filterState.status || vStatus === filterState.status;

      const vForm = String(v.party_type || "").toUpperCase() + "|" + String(v.category || "").toUpperCase();
      const matchesForm = !filterState.form || vForm === filterState.form;

      return matchesSearch && matchesStatus && matchesForm;
    });

    if (!filtered.length) {
      const hasFilters = q || filterState.status || filterState.form;
      $("#vendorBody").innerHTML = `
        <tr>
          <td colspan="6" style="text-align:center;padding:36px 16px;color:#94A3B8">
            ${hasFilters ? "No vendors match the current filters." : "No vendors found."}
          </td>
        </tr>`;
      renderPagination();
      return;
    }

    $("#vendorBody").innerHTML = filtered.map(v => {
      const vStatus = v.kycStatus || v.status || "INVITED";
      const isInvited = vStatus === "INVITED";
      const vEmail = v.vendorEmail || v.email || "-";
      const vCompany = v.companyName || v.company_name || "-";
      const vId = v.caseId || v._id || "";

      return `
        <tr>
          <td style="font-weight:600">${esc(v.vendorName || v.name)}</td>
          <td style="color:var(--text-dim);font-size:11.5px">${esc(vEmail)}</td>
          <td style="color:var(--text-dim);font-size:11.5px;font-weight:500">${esc(vCompany)}</td>
          <td><span class="dim" style="font-size:11.5px">${esc(v.kycType)}</span></td>
          <td>${badge(vStatus)}</td>
          <td>
            ${
              isInvited || !vId
                ? `<span class="link disabled" title="Vendor has not submitted KYC details yet">View</span>`
                : `<button class="link" data-view="${esc(vId)}">View</button>`
            }
          </td>
        </tr>`;
    }).join("");

    renderPagination();
  }

  // Signature is used to decide whether an incoming model update actually
  // changed vendor data (so we don't blow away scroll/focus/search state
  // on every unrelated model change, e.g. sendInvite's status ticking over).
  function computeSignature(list) {
    return JSON.stringify((list || []).map(v =>
      (v._id || v.case_id || "") + "|" +
      (v.status || "") + "|" +
      (v.vendor_contact_email || v.vendorEmail || "") + "|" +
      (v.vendor_working_name || v.vendorName || "")
    ));
  }

  function syncVendorsFromModel() {
    if (typeof appsmith !== "undefined" && appsmith.model) {
      const dbList = appsmith.model.allVendors || [];
      vendors = dbList.map(normalizeVendor).filter(Boolean);
      totalRecords = Number(appsmith.model.totalRecords) || 0;
      pageSize = Number(appsmith.model.pageSize) || 10;
      if (appsmith.model.page) currentPage = Number(appsmith.model.page);
    }

    recalculateCounts();
    renderPipelineCards();
    renderVendors(currentSearch());
    renderPagination();
  }

  $("#vendorSearch").addEventListener("input", e => renderVendors(e.target.value));

  /* ---- Filter dropdown wiring ---- */
  $("#statusFilterBtn").addEventListener("click", e => {
    e.stopPropagation();
    openDropdownPortal(e.currentTarget, STATUS_FILTER_OPTIONS, filterState.status, val => {
      filterState.status = val;
      renderFilterButtons();
      renderVendors(currentSearch());
    });
  });

  $("#formFilterBtn").addEventListener("click", e => {
    e.stopPropagation();
    openDropdownPortal(e.currentTarget, FORM_FILTER_OPTIONS, filterState.form, val => {
      filterState.form = val;
      renderFilterButtons();
      renderVendors(currentSearch());
    });
  });

  $("#clearFilters").addEventListener("click", () => {
    filterState.status = "";
    filterState.form = "";
    closeAllDropdowns();
    renderFilterButtons();
    renderVendors(currentSearch());
  });

  renderFilterButtons();

  $("#vendorBody").addEventListener("click", async e => {
    const b = e.target.closest("button[data-view]");
    if (!b) return;

    // Lookup by id (not row index) so it stays correct when filters/search hide rows
    const selectedVendor = vendors.find(v => (v.caseId || v._id) === b.dataset.view);
    if (!selectedVendor) return;

    const selectedVendorId = selectedVendor.caseId || selectedVendor._id || selectedVendor.id;

    if (typeof appsmith !== "undefined") {
      if (appsmith.updateModel) {
        await appsmith.updateModel({ selectedVendorId });
      }
      if (appsmith.triggerEvent) {
        appsmith.triggerEvent("onViewVendor");
      }
    }
  });

  /* ============ Modal & Dropdown ============ */
  let inviteState = { name: "", email: "", companyName: "", party: null, category: null, serviceSupplier: false };
  let activeDropdown = null;

  function closeAllDropdowns() {
    $("#portalDropdownRoot").innerHTML = "";
    document.querySelectorAll(".u-select").forEach(el => el.classList.remove("active"));
    activeDropdown = null;
  }

  function openDropdownPortal(targetTriggerEl, options, selectedValue, onSelect) {
    if (activeDropdown === targetTriggerEl) {
      closeAllDropdowns();
      return;
    }
    closeAllDropdowns();

    const parentSelect = targetTriggerEl.closest(".u-select");
    if (parentSelect) parentSelect.classList.add("active");
    activeDropdown = targetTriggerEl;

    const rect = targetTriggerEl.getBoundingClientRect();
    const spaceBelow = window.innerHeight - rect.bottom;
    const menuHeight = Math.min(options.length * 36 + 10, 200);
    const openUpwards = spaceBelow < menuHeight && rect.top > menuHeight;

    const menu = document.createElement("div");
    menu.className = "u-floating-menu show";
    menu.style.width = rect.width + "px";
    menu.style.left = rect.left + "px";

    if (openUpwards) {
      menu.style.bottom = (window.innerHeight - rect.top + 4) + "px";
      menu.style.top = "auto";
    } else {
      menu.style.top = (rect.bottom + 4) + "px";
      menu.style.bottom = "auto";
    }

    menu.innerHTML = options.map(opt => `
      <div class="u-item ${selectedValue === opt.value ? "sel" : ""}" data-val="${esc(opt.value)}">
        <span>${esc(opt.label)}</span>
        <span class="check">${ICON.tick}</span>
      </div>
    `).join("");

    menu.querySelectorAll(".u-item").forEach(item => {
      item.addEventListener("click", e => {
        e.stopPropagation();
        onSelect(item.dataset.val);
        closeAllDropdowns();
      });
    });

    $("#portalDropdownRoot").appendChild(menu);
  }

  // ---- Duplicate-invite check ----
  // Uses every email in kyc_cases (model.existingEmails from getVendorEmails),
  // plus the rows currently loaded, so it works across all pages.
  function isAlreadyInvited(email) {
    const e = String(email || "").trim().toLowerCase();
    if (!e) return false;
    const fromModel = (typeof appsmith !== "undefined" && appsmith.model && Array.isArray(appsmith.model.existingEmails))
      ? appsmith.model.existingEmails : [];
    if (fromModel.some(x => String(x || "").trim().toLowerCase() === e)) return true;
    return vendors.some(v => String(v.vendorEmail || v.vendor_contact_email || v.email || "").trim().toLowerCase() === e);
  }

  function syncEmailError() {
    const input = $("#vEmail");
    const box = $("#vEmailErr");
    if (!input || !box) return;
    const dup = isAlreadyInvited(input.value);
    box.style.display = dup ? "block" : "none";
    input.style.borderColor = dup ? "#DC2626" : "";
    input.style.background = dup ? "#FEF2F2" : "";
  }

  function validateEmailFormat(email) {
    return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(email).trim());
  }

  function getMissingFields() {
    const name = ($("#vName") ? $("#vName").value : inviteState.name || "").trim();
    const email = ($("#vEmail") ? $("#vEmail").value : inviteState.email || "").trim();

    const missing = [];
    if (!name) missing.push("Vendor name");
    if (!email) {
      missing.push("Vendor email");
    } else if (!validateEmailFormat(email)) {
      missing.push("Valid email address");
    } else if (isAlreadyInvited(email)) {
      missing.push("A different email (this vendor is already invited)");
    }
    if (!inviteState.companyName) missing.push("Company name");
    if (!inviteState.party) missing.push("Party type");
    if (!inviteState.category) missing.push("Category");

    return missing;
  }

  function syncModalButton() {
    const btn = $("#sendInvite");
    const bubble = $("#tooltipBubble");
    if (!btn || !bubble) return;

    const missing = getMissingFields();
    if (missing.length === 0) {
      btn.disabled = false;
      btn.style.background = TEAL;
      btn.style.borderColor = TEAL;
      btn.style.color = "#fff";
      bubble.style.display = "none";
    } else {
      btn.disabled = true;
      btn.style.background = "#E2E8F0";
      btn.style.borderColor = "#E2E8F0";
      btn.style.color = "#94A3B8";
      bubble.style.display = "block";
      bubble.textContent = "Please fill: " + missing.join(", ");
    }
  }

  $("#openInvite").addEventListener("click", () => {
    inviteState = { name: "", email: "", companyName: "", party: null, category: null, serviceSupplier: false };
    renderInvite();
  });

  function closeInvite() {
    closeAllDropdowns();
    $("#modalRoot").innerHTML = "";
  }

  function renderInvite() {
    const st = inviteState;
    const missing = getMissingFields();
    const isValid = missing.length === 0;
    const showSvc = isServiceSupplierApplicable(st.party, st.category);
    if (!showSvc) st.serviceSupplier = false;

    $("#modalRoot").innerHTML = `
      <div class="overlay" data-close-invite>
        <div class="modal" id="inviteModal">
          <div class="modal-head">
            <div>
              <div class="t">Invite vendor for KYC</div>
              <div class="s">Vendor will receive an email with a pre-configured KYC link</div>
            </div>
            <button class="xbtn" data-close-invite>${ICON.close}</button>
          </div>

          <div class="modal-body" id="modalScrollBody">
            <div class="grid2">
              <div>
                <label class="fl">Vendor name *</label>
                <input class="fld" id="vName" placeholder="Company / firm name" value="${esc(st.name)}" />
              </div>
              <div>
                <label class="fl">Vendor email *</label>
                <input class="fld" id="vEmail" type="email" placeholder="vendor@company.com" value="${esc(st.email)}" />
                <div id="vEmailErr" style="display:none;color:#DC2626;font-size:12px;margin-top:4px">This email has already been invited.</div>
              </div>
            </div>

            <div>
              <label class="fl">Company Name *</label>
              <div class="u-select" id="companySelectWrap">
                <button type="button" class="u-select-btn" id="companySelectBtn">
                  <span>${st.companyName ? esc(st.companyName) : '<span class="ph">Select Company *</span>'}</span>
                  <span class="arrow">${ICON.chevronDown}</span>
                </button>
              </div>
            </div>

            <div>
              <div class="sect-lbl">Select party type *</div>
              <div class="grid4">
                ${PARTIES.map(p => `
                  <button type="button" class="party ${st.party === p.id ? "on" : ""}" data-party="${p.id}">
                    <span class="pill" style="background:${p.tagBg};color:${p.tagFg};font-size:11px">${p.tag}</span>
                    <div class="ic">${p.icon}</div>
                    <div class="nm">${p.label}</div>
                    <div class="sb">${p.sub}</div>
                  </button>`).join("")}
              </div>
            </div>

            ${st.party ? `
            <div>
              <label class="sect-lbl" style="display:block;margin-bottom:0">Select category *</label>
              <div class="u-select" id="catSelectWrap">
                <button type="button" class="u-select-btn" id="catSelectBtn">
                  <span>${st.category ? esc(st.category) : '<span class="ph">Choose a category</span>'}</span>
                  <span class="arrow">${ICON.chevronDown}</span>
                </button>
              </div>
            </div>` : ""}

            ${showSvc ? `
            <div>
              <label style="display:flex;gap:10px;align-items:flex-start;cursor:pointer">
                <input type="checkbox" id="svcSupplier" ${st.serviceSupplier ? "checked" : ""}
                  style="margin-top:3px;width:15px;height:15px;accent-color:${TEAL};cursor:pointer" />
                <span style="font-size:13px;font-weight:600;color:var(--danger);line-height:1.4">
                  This vendor provides services (Import of Service)
                </span>
              </label>
            </div>` : ""}
          </div>

          <div class="modal-foot">
            <button class="btn btn-outline" data-close-invite>Cancel</button>
            <div class="tooltip-wrap">
              <div class="tooltip-bubble" id="tooltipBubble" style="${isValid ? "display:none" : ""}">
                Please fill: ${esc(missing.join(", "))}
              </div>
              <button class="btn" id="sendInvite" ${!isValid ? "disabled" : ""}
                style="${isValid ? "background:" + TEAL + ";border-color:" + TEAL + ";color:#fff" : ""}">
                Send Invite
              </button>
            </div>
          </div>
        </div>
      </div>`;

    const root = $("#modalRoot");
    wireCloseHandlers(root, "[data-close-invite]", closeInvite);

    const nameInput = $("#vName");
    const emailInput = $("#vEmail");

    if (nameInput) {
      nameInput.addEventListener("input", e => {
        inviteState.name = e.target.value;
        syncModalButton();
      });
    }

    if (emailInput) {
      emailInput.addEventListener("input", e => {
        inviteState.email = e.target.value;
        syncEmailError();
        syncModalButton();
      });
      syncEmailError();
    }

    const compBtn = $("#companySelectBtn");
    if (compBtn) {
      compBtn.addEventListener("click", e => {
        e.stopPropagation();
        const options = COMPANY_OPTIONS.map(c => ({ value: c, label: c }));
        openDropdownPortal(compBtn, options, inviteState.companyName, val => {
          inviteState.companyName = val;
          renderInvite();
        });
      });
    }

    const catBtn = $("#catSelectBtn");
    if (catBtn && st.party) {
      catBtn.addEventListener("click", e => {
        e.stopPropagation();
        const options = CATEGORIES[st.party].map(c => ({ value: c, label: c }));
        openDropdownPortal(catBtn, options, inviteState.category, val => {
          inviteState.category = val;
          renderInvite();
        });
      });
    }

    const scrollBody = $("#modalScrollBody");
    if (scrollBody) {
      scrollBody.addEventListener("scroll", () => closeAllDropdowns());
    }

    root.querySelectorAll("[data-party]").forEach(btn => {
      btn.addEventListener("click", () => {
        closeAllDropdowns();
        inviteState.name = $("#vName") ? $("#vName").value : inviteState.name;
        inviteState.email = $("#vEmail") ? $("#vEmail").value : inviteState.email;
        inviteState.party = btn.dataset.party;
        inviteState.category = null;
        renderInvite();
      });
    });

    const svc = $("#svcSupplier");
    if (svc) {
      svc.addEventListener("change", e => { inviteState.serviceSupplier = e.target.checked; });
    }

    const send = $("#sendInvite");
    send.addEventListener("click", () => {
      closeAllDropdowns();
      const missingFields = getMissingFields();
      if (missingFields.length > 0) {
        toast("Please fill: " + missingFields.join(", "), "err");
        return;
      }

      const vendorName = inviteState.name.trim();
      const vendorEmail = inviteState.email.trim().toLowerCase();
      const selectedCompany = inviteState.companyName;
      const partyObj = PARTIES.find(p => p.id === inviteState.party);
      const partyLabel = partyObj ? partyObj.label : "";
      const categoryVal = inviteState.category || "";

      const partyCode = PARTY_CODE[inviteState.party] || "";
      const categoryCode = CATEGORY_CODE[categoryVal] || "";

      const newRecord = {
        vendorName: vendorName,
        vendorEmail: vendorEmail,
        companyName: selectedCompany,
        company_name: selectedCompany,
        partyType: partyLabel,
        kycType: partyLabel + (categoryVal ? " - " + categoryVal : ""),
        kycStatus: "INVITED",
        createdAt: new Date().toISOString(),
        party_type: partyCode,
        category: categoryCode,
        service_supplier: isServiceSupplierApplicable(inviteState.party, categoryVal)
          ? !!inviteState.serviceSupplier
          : false
      };

      // ---- OPTIMISTIC INSERT: table turant update, backend ka wait nahi ----
      const optimisticVendor = { ...newRecord, _optimistic: true };
      vendors = [optimisticVendor, ...vendors];
      recalculateCounts();
      renderPipelineCards();
      renderVendors(currentSearch());

      // 1. Modal band karo
      closeInvite();

      // 2. Halka non-blocking feedback
      toast("Sending invite…");
      isInvitingVendor = true;

      // 3. Appsmith ko trigger karo — background me chalega
      if (typeof appsmith !== "undefined") {
        if (appsmith.updateModel) {
          appsmith.updateModel({ newInvite: newRecord });
        }
        if (appsmith.triggerEvent) {
          appsmith.triggerEvent("onInviteSent", newRecord);
        }
      }
    });
  }

  document.addEventListener("click", e => {
    if (!e.target.closest("#portalDropdownRoot") && !e.target.closest(".u-select-btn")) {
      closeAllDropdowns();
    }
  });

  /* ============ Drawer ============ */
  let drawerState = { vendor: null };

  function openDrawer(vendor) {
    drawerState = { vendor };
    renderDrawer();
  }
  function closeDrawer() { $("#drawerRoot").innerHTML = ""; }

  function renderDrawer() {
    const { vendor } = drawerState;
    if (!vendor) return;

    const vStatus = vendor.kycStatus || vendor.status || "INVITED";
    const vName = vendor.vendorName || vendor.name;
    const vEmail = vendor.vendorEmail || vendor.email || "-";
    const vCompany = vendor.companyName || vendor.company_name || "-";

    const details = [
      ["Vendor name", vName],
      ["Email address", vEmail],
      ["Company Entity", vCompany],
      ["Party Type", vendor.partyType || vendor.party || "-"],
      ["KYC Type", vendor.kycType || "-"],
      ["Status", vStatus],
      ["Service Supplier", vendor.service_supplier ? "Yes" : "No"],
      ["Case ID", vendor.caseId || "Pending"],
      ["Date Added", vendor.createdAt ? new Date(vendor.createdAt).toLocaleDateString() : "Just now"],
    ];

    const body = `
      <div class="kv">
        ${details.map(([k, v]) => `<div><div class="k">${esc(k)}</div><div class="v">${esc(v)}</div></div>`).join("")}
      </div>`;

    $("#drawerRoot").innerHTML = `
      <div class="drawer-overlay" data-close-drawer>
        <div class="drawer">
          <div class="drawer-head">
            <div style="display:flex;align-items:flex-start;justify-content:space-between">
              <div>
                <div style="font-size:17px;font-weight:600">${esc(vName)}</div>
                <div style="font-size:12.5px;color:var(--text-dim);margin-top:2px">${esc(vEmail)}</div>
              </div>
              <button class="xbtn" data-close-drawer>${ICON.close}</button>
            </div>
            <div style="display:flex;gap:8px;margin-top:10px">
              <span class="pill" style="background:#EEF9F7;color:${TEAL};font-size:11px">${esc(vendor.kycType)}</span>
              ${badge(vStatus)}
            </div>
          </div>
          <div class="drawer-body">${body}</div>
          <div class="drawer-foot">
            <div class="right">
              <button class="btn btn-solid" data-close-drawer>Done</button>
            </div>
          </div>
        </div>
      </div>`;

    const root = $("#drawerRoot");
    wireCloseHandlers(root, "[data-close-drawer]", closeDrawer);
  }

  document.addEventListener("keydown", e => {
    if (e.key === "Escape") {
      closeAllDropdowns();
      closeInvite();
      closeDrawer();
    }
  });

  syncVendorsFromModel();
  lastVendorsSignature = computeSignature(
    typeof appsmith !== "undefined" ? appsmith.model?.allVendors : null
  ) + "_" + ((typeof appsmith !== "undefined" && appsmith.model?.totalRecords) || 0);

  if (typeof appsmith !== "undefined" && appsmith.onModelChange) {
    appsmith.onModelChange(() => {
      const isQueryLoading = Boolean(appsmith.model?.isLoading);

      if (isQueryLoading) {
        setTableLoader(true, "Refreshing vendors...");
        return;
      }

      setTableLoader(false);
      showScreenLoader(false);
      isInvitingVendor = false;

      // Sirf tab re-render karo jab vendor data actually badla ho
      const newSignature = computeSignature(appsmith.model?.allVendors) + "_" + (appsmith.model?.totalRecords || 0);
      if (newSignature === lastVendorsSignature) {
        return;
      }
      lastVendorsSignature = newSignature;

      const searchEl = $("#vendorSearch");
      const hadFocus = document.activeElement === searchEl;
      const caretPos = searchEl ? searchEl.selectionStart : null;
      const searchVal = searchEl ? searchEl.value : "";

      // Table data fresh model se update karo (optimistic row asli backend row se replace ho jaayegi).
      // Active filters (filterState) automatically apply ho jaayenge.
      syncVendorsFromModel();

      const newSearchEl = $("#vendorSearch");
      if (newSearchEl) {
        newSearchEl.value = searchVal;
        if (hadFocus) {
          newSearchEl.focus();
          if (caretPos !== null) {
            try { newSearchEl.setSelectionRange(caretPos, caretPos); } catch (e) {}
          }
        }
      }
    });
  }
}

if (typeof appsmith !== "undefined" && appsmith.onReady) {
  appsmith.onReady(() => { initApp(); });
} else {
  initApp();
}
